int gcd(int a,int b){
    if(b==0) return a;
    return gcd(b,a%b);
}

快速幂
int qpow(int a,int b,int mod){
    int sum=1;
    while(b){
        if(b&1){
            sum=(sum*a)%mod;
        }
        a=(a*a)%mod;
        b>>=1;
    }
    return sum;
}
